INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('beisypuge6dfdfbeisx18h2zvrlcf8mb', '2026-Q3', 'Set/2026 (T3)', '2026-09-24T17:49'::timestamptz, 'Wanderson Mário Cavalcante Olímpio', 'wanderson mario cavalcante olimpio', 'PHARUS', 'Tales Salinas Rozo', 6.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Só estou encerrando o primeiro ano e infelizmente por planejamento pessoal, não consegui implementar todas as estratégias que eu gostaria. Meu intuito seria aproveitar mais do ecossistema do Grupo Quarta Via. Como eu não consegui fazer implementação de fato e a que eu fiz, ainda não concluí, entendo que preciso de mais tempo e verificar as coisas de fato acontecerem para poder indicar pra algum familiar ou amigo. Aqui nós estamos falando de lhe dar com dinheiro, com patrimônio, então eu tenho muito cuidado para indicar a qualquer familiar visto que eu ainda não pude ter o feedback prático das implementações que eu fiz. De repente, futuramente, observando do ponto de vista prático que obtivemos êxito, não teria problema indicar para alguém conhecido.', 'A nota vai depender muito do momento individual de cada cliente. Meu intuito era implementar estratégias que me dessem melhor retorno nos investimentos, trazendo isso para economia real. Gosto bastante das ideias, da clareza do estrategista patrimonial, mas particularmente eu entendo que para implementar as estratégias, você precisa de fato ter capital sobrando. Não era meu caso. Tenho capital na reserva mas são valores que não me sentiria ainda seguro de colocar em alguma implementação maior. Estou aguardando ter o retorno diante do leilão de imóvel que participo, vendo na prática as coisas acontecerem, esse dinheiro retornando pra minha conta, vai me dar mais confiança para futuras implementações. Mas por enquanto, até encerrar alguma estratégia, não tenho como dar 9 ou 10', NULL, 'Primeiríssimo lugar, o valor anual do contrato.  Entendo que é considerável e se colocarmos no papel, para quem busca investir, tem que considerar esse valor que é alocado para poder fazer parte do ecossistema pelo período de 1 ano. E entendo que pra tirar é valer a pena o investimento, meu retorno tem que ser bem maior que esses 22 mil reais. Só que pra isso, eu tenho que ter disponível capital relevante para fazer as aplicações e estratégias. Pode ser que a tendência do contrato anual seja só aumentar, como que posso ter retorno acima de 22mil no ano de forma consistente, isso dá quase 2 mil por mês. Parte relevante dos investimentos acaba sendo “perdida” pelo o que eu considero um alto preço do contrato. Como disse anteriormente, só faria sentido de fato, para quem tem muito patrimônio e os 22 mil seriam irrelevantes. Pois poderia participar de várias estratégias', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'beisypuge6dfdfbeisx18h2zvrlcf8mb', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('d9dpxthxgmet4iy9d9dpxt0utlawsrw7', '2026-Q3', 'Set/2026 (T3)', '2026-09-24T18:30'::timestamptz, 'Fernanda Cardoso Chaves', 'fernanda cardoso chaves', 'PHARUS', 'Samuel Araújo', 10.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Atenção recebida pelo meu assessor, pois estou muito insegura ainda em relação aos investimentos e renovação da consultoria. Mas tenho fé, não vou desistir. Muito obrigada, Samuel, pela paciência em me explicar tudo de novo, e de novo, e de novo, com paciência e competência!', NULL, 'A atenção dada pelo meu consultor Samuel e busca de alternativas para o pagamento da consultoria.', 'Ver o retorno dos investimentos na vida real.', 'Gostaria de mostrar a empresa para minhas irmãs e cunhado. Teria que marcar uma reunião ou tenho que esperar só quando for lançado novamente no mercado, como eu fiz? Eu encontrei a Quartavia através do Instagram e participei por 1 semana das lives, no final de semana entrei.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'd9dpxthxgmet4iy9d9dpxt0utlawsrw7', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
