al, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('2ysogr0jkwotz45158g2ysognc5v9nbl', '2026-Q3', 'Set/2026 (T3)', '2026-09-26T09:58'::timestamptz, 'Carlos Henrique Leão de Faria', 'carlos henrique leao de faria', 'PHARUS', 'João Aliceda', 9.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Totalmente no caminho', 'Entendi o método, mas ainda não implementei o suficiente', 'No momento, paciência comigo ;-)', NULL, 'Sei e confio na competência e qualidade da proposta de valor da Quarta Via, bem como evidencio a habilidade no trato com a questão e a pessoa, mas como estou enfrentando um momento de muita confusão e desorganização, eu mesmo tenho protelado minha ação, e assim, a paciência de vocês em respeito a mim, tem me confortado. Será muito provavelmente um 10 mais à frente ao avançar com vocês e retomar as rédeas da minha atual vida financeira.', 'Ainda estou muito no início dessa jornada em comum para dizer com precisão, e preciso avançar mais primeiro.', 'Apenas agradecê-los e neste momento ainda mais pela baita paciência com a qual tem me tratado.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '2ysogr0jkwotz45158g2ysognc5v9nbl', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategist